-- Fietsenwinkel De Spaak: fictieve database voor Process Data in Organisations (16021)
-- Werkt in MySQL 8+ en MariaDB. Laad dit hele script in één keer.

DROP DATABASE IF EXISTS spaak;
CREATE DATABASE spaak;
USE spaak;

CREATE TABLE klant (
  klant_id   INT PRIMARY KEY,
  naam       VARCHAR(80) NOT NULL,
  telefoon   VARCHAR(15),
  email      VARCHAR(120)
);

CREATE TABLE fiets (
  fiets_id   INT PRIMARY KEY,
  klant_id   INT NOT NULL,
  merk       VARCHAR(40) NOT NULL,
  type       VARCHAR(40),
  is_ebike   BOOLEAN NOT NULL,
  FOREIGN KEY (klant_id) REFERENCES klant(klant_id)
);

CREATE TABLE monteur (
  monteur_id INT PRIMARY KEY,
  naam       VARCHAR(80) NOT NULL
);

CREATE TABLE leverancier (
  leverancier_id  INT PRIMARY KEY,
  naam            VARCHAR(80) NOT NULL,
  levertijd_dagen INT
);

CREATE TABLE onderdeel (
  onderdeel_id   INT PRIMARY KEY,
  leverancier_id INT NOT NULL,
  naam           VARCHAR(80) NOT NULL,
  prijs          DECIMAL(7,2),
  voorraad       INT NOT NULL DEFAULT 0,
  FOREIGN KEY (leverancier_id) REFERENCES leverancier(leverancier_id)
);

CREATE TABLE reparatie (
  reparatie_id  INT PRIMARY KEY,
  fiets_id      INT NOT NULL,
  monteur_id    INT NOT NULL,
  omschrijving  VARCHAR(200),
  datum_binnen  DATE NOT NULL,
  datum_beloofd DATE NOT NULL,
  datum_klaar   DATE,
  status        VARCHAR(30) NOT NULL,
  FOREIGN KEY (fiets_id) REFERENCES fiets(fiets_id),
  FOREIGN KEY (monteur_id) REFERENCES monteur(monteur_id)
);

CREATE TABLE reparatie_onderdeel (
  reparatie_id INT,
  onderdeel_id INT,
  aantal       INT NOT NULL DEFAULT 1,
  besteld_op   DATE,
  geleverd_op  DATE,
  PRIMARY KEY (reparatie_id, onderdeel_id),
  FOREIGN KEY (reparatie_id) REFERENCES reparatie(reparatie_id),
  FOREIGN KEY (onderdeel_id) REFERENCES onderdeel(onderdeel_id)
);

